"""M-Coloring Problem — backtracking over the nodes.

Colour node by node; a colour is legal when no already-coloured neighbour uses
it. Failing fast on the first uncolourable node is the entire pruning.

Time: O(m^n)   Space: O(n)
"""
from typing import List


class Solution:
    def graphColoring(self, n: int, edges: List[List[int]], m: int) -> bool:
        graph = [[] for _ in range(n)]
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        colour = [0] * n

        def assign(node: int) -> bool:
            if node == n:
                return True
            used = {colour[nb] for nb in graph[node]}
            for candidate in range(1, m + 1):
                if candidate in used:
                    continue
                colour[node] = candidate
                if assign(node + 1):
                    return True
                colour[node] = 0
            return False

        return assign(0)
